package com.powercms.cms.delivery.navigation;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="url_rewrite_rule") public class UrlRewriteRuleEntity {
 @Id private UUID id; @Column(name="site_id",nullable=false) private UUID siteId; @Column(nullable=false,length=200) private String name; @Column(nullable=false,length=512) private String pattern; @Column(nullable=false,length=1000) private String replacement; @Column(nullable=false) private int priority; @Column(nullable=false,length=20) private String status="DRAFT"; @Version @Column(name="lock_version",nullable=false) private long lockVersion; @Column(name="created_by",length=100) private String createdBy; @Column(name="created_at",nullable=false,updatable=false) private Instant createdAt; @Column(name="updated_at",nullable=false) private Instant updatedAt;
 @PrePersist void create(){if(id==null)id=UUID.randomUUID();createdAt=updatedAt=Instant.now();} @PreUpdate void update(){updatedAt=Instant.now();}
 public UUID getId(){return id;} public UUID getSiteId(){return siteId;} public void setSiteId(UUID v){siteId=v;} public String getName(){return name;} public void setName(String v){name=v;} public String getPattern(){return pattern;} public void setPattern(String v){pattern=v;} public String getReplacement(){return replacement;} public void setReplacement(String v){replacement=v;} public int getPriority(){return priority;} public void setPriority(int v){priority=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} public long getLockVersion(){return lockVersion;} public String getCreatedBy(){return createdBy;} public void setCreatedBy(String v){createdBy=v;} public Instant getCreatedAt(){return createdAt;} public Instant getUpdatedAt(){return updatedAt;}
}